<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import UiIcon from './UiIcon.vue'

type Kind = 'wizard' | 'main' | 'chat' | 'model' | 'memory' | 'ai' | 'voice' | 'skills' | 'mcp' | 'plugins' | 'automation' | 'debug'
type Primary = 'home' | 'talk' | 'model' | 'memory' | 'settings'
type Setting = 'ai' | 'voice' | 'skills' | 'mcp' | 'plugins' | 'automation' | 'debug'
const props = defineProps<{ kind: Kind }>()
const primaryItems: Array<{ key: Primary; label: string; icon: string }> = [
  { key: 'home', label: '主页', icon: 'noriOS' }, { key: 'talk', label: '对话', icon: 'send' },
  { key: 'model', label: '模型', icon: 'package' }, { key: 'memory', label: '长期记忆', icon: 'file' },
  { key: 'settings', label: '设置', icon: 'settings' }
]
const settingItems: Array<{ key: Setting; label: string; icon: string }> = [
  { key: 'ai', label: 'AI 与模型', icon: 'cpu' }, { key: 'voice', label: '语音', icon: 'volume' },
  { key: 'skills', label: '技能', icon: 'sparkles' }, { key: 'mcp', label: 'MCP', icon: 'server' },
  { key: 'plugins', label: '插件', icon: 'plug' }, { key: 'automation', label: '自动化', icon: 'terminal' },
  { key: 'debug', label: '调试与诊断', icon: 'activity' }
]
const starts: Record<Kind, { primary: Primary; setting?: Setting }> = {
  wizard: { primary: 'home' }, main: { primary: 'home' }, chat: { primary: 'talk' }, model: { primary: 'model' }, memory: { primary: 'memory' },
  ai: { primary: 'settings', setting: 'ai' }, voice: { primary: 'settings', setting: 'voice' }, skills: { primary: 'settings', setting: 'skills' },
  mcp: { primary: 'settings', setting: 'mcp' }, plugins: { primary: 'settings', setting: 'plugins' }, automation: { primary: 'settings', setting: 'automation' }, debug: { primary: 'settings', setting: 'debug' }
}
const primary = ref<Primary>('home'), setting = ref<Setting>('ai'), collapsed = ref(false), petVisible = ref(true), minimized = ref(false)
const toast = ref('')
let toastTimer: ReturnType<typeof setTimeout> | undefined
const notify = (text: string) => { toast.value = text; if (toastTimer) clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.value = '', 1800) }
const reset = () => { const start = starts[props.kind]; primary.value = start.primary; if (start.setting) setting.value = start.setting }
watch(() => props.kind, reset, { immediate: true })
const primaryLabel = computed(() => primaryItems.find(x => x.key === primary.value)?.label ?? '主页')
const settingLabel = computed(() => settingItems.find(x => x.key === setting.value)?.label ?? '设置')

const step = ref(0), language = ref('zh-CN'), wizardModel = ref('arg-nori'), wizardKey = ref(''), wizardModelName = ref(''), wizardBusy = ref(false)
const steps = ['欢迎', '语言', '模型', 'AI', '就绪']
const fetchWizardModels = () => {
  if (!wizardKey.value.trim()) return notify('先填写用于演示的 API Key')
  wizardBusy.value = true
  setTimeout(() => { wizardBusy.value = false; wizardModelName.value = 'example-chat'; notify('已获取演示模型') }, 550)
}

const chatInput = ref(''), chatReply = ref('早上好。这里是文档里的交互演示。')
const sendChat = () => { if (!chatInput.value.trim()) return; const text = chatInput.value; chatInput.value = ''; chatReply.value = `收到「${text}」。这条回复只存在于文档演示里。` }
const selectedModel = ref('arg-nori'), modelScale = ref(1), expression = ref('默认')
const memoryQuery = ref(''), archived = ref(false)

const aiProvider = ref('openai'), aiUrl = ref('https://api.openai.com/v1'), aiKey = ref(''), aiModel = ref(''), aiStatus = ref('')
const aiDefaults: Record<string, string> = { openai: 'https://api.openai.com/v1', openai_responses: 'https://api.openai.com/v1', anthropic: 'https://api.anthropic.com/v1', google: 'https://generativelanguage.googleapis.com/v1beta' }
const changeProvider = () => { aiUrl.value = aiDefaults[aiProvider.value]; aiModel.value = ''; aiStatus.value = '' }
const fakeAi = (test = false) => { aiStatus.value = test ? '正在测试演示连接…' : '正在获取演示模型…'; setTimeout(() => { aiModel.value = aiModel.value || 'example-chat'; aiStatus.value = test ? '连接测试成功 · 演示结果' : '已获取演示模型' }, 500) }

const volume = ref(72), ttsProvider = ref('openai'), ttsSpeed = ref(1), autoplay = ref(true), voiceStatus = ref('')
const testVoice = () => { voiceStatus.value = '正在试听…'; setTimeout(() => voiceStatus.value = '试听完成 · 没有发送真实请求', 650) }
const skillWeb = ref(true), skillReminder = ref(true), mcpEnabled = ref(true), pluginEnabled = ref(true), automationEnabled = ref(false)
const diagnostics = ref('')
</script>

<template>
  <div class="ndp">
    <button v-if="minimized" class="minimized" type="button" @click="minimized = false"><span class="brand-dot"><UiIcon name="sparkles" :size="12" /></span><strong>Nori</strong><span>已最小化 · 点击恢复</span></button>
    <div v-else class="window">
      <header class="titlebar">
        <div class="title-left"><span class="traffic"><button class="close" type="button" @click="notify('文档演示不会退出真实 Nori')"><UiIcon name="close" :size="7" /></button><button v-if="kind !== 'wizard'" class="min" type="button" @click="minimized = true"><UiIcon name="minus" :size="7" /></button></span><span class="brand-dot"><UiIcon name="sparkles" :size="11" /></span><strong>Nori</strong><span class="pet-os">Nori OS</span></div>
        <div v-if="kind === 'wizard'" class="step-pill"><span v-for="(name, i) in steps" :key="name" :class="{ on: i === step, done: i < step }"><i />{{ i === step ? name : '' }}</span></div>
        <div class="title-right"><span v-if="kind === 'wizard'" class="progress"><i v-for="i in 5" :key="i" :class="{ on: i <= step + 1 }" /><b>{{ step + 1 }} / 5</b></span><span v-else class="location"><UiIcon :name="primary === 'settings' ? 'settings' : primary === 'talk' ? 'send' : primary === 'model' ? 'package' : primary === 'memory' ? 'file' : 'noriOS'" :size="12" />{{ primaryLabel }}</span></div>
      </header>

      <template v-if="kind === 'wizard'">
        <main class="wizard-stage" :data-step="step">
          <section v-if="step === 0" class="welcome"><div><span class="chip teal">Live2D Cyber Companion</span><h2>欢迎来到 Nori</h2><p>完成语言、伴侣模型和 AI 服务的基础设置。这里的操作只用于文档演示。</p><div class="features"><span class="chip"><UiIcon name="sparkles" :size="11" /> Live2D</span><span class="chip"><UiIcon name="cpu" :size="11" /> AI 对话</span><span class="chip"><UiIcon name="package" :size="11" /> 本地扩展</span></div><div class="link-grid"><button @click="notify('Steam 链接演示')"><UiIcon name="steam" :size="14" mode="fill" /><span><b>Steam</b><small>查看商店页</small></span></button><button @click="notify('noriOS 链接演示')"><UiIcon name="noriOS" :size="14" /><span><b>noriOS</b><small>了解更多</small></span></button><button @click="notify('群号已模拟复制')"><UiIcon name="qq" :size="14" mode="fill" /><span><b>交流群</b><small>复制群号</small></span></button><button @click="notify('Bilibili 链接演示')"><UiIcon name="bilibili" :size="14" mode="fill" /><span><b>Bilibili</b><small>项目动态</small></span></button></div></div><div class="logo-stage"><i /><img src="/logo.png" alt="Nori" /><span>- N O R I -</span></div></section>
          <section v-else-if="step === 1" class="wizard-center"><span class="chip teal">Language Preference</span><h2>选择界面语言</h2><p>选中的语言会用于 Nori 的界面与提示。</p><div class="choice-grid"><button :class="{ selected: language === 'zh-CN' }" @click="language = 'zh-CN'"><span class="flag">简</span><span><b>简体中文</b><small>Chinese (Simplified)</small></span></button><button :class="{ selected: language === 'en-US' }" @click="language = 'en-US'"><span class="flag">EN</span><span><b>English</b><small>English (US)</small></span></button></div></section>
          <section v-else-if="step === 2" class="wizard-center"><span class="chip teal">Live2D Companion</span><h2>选择伴侣模型</h2><p>之后仍可以在模型管理中切换。</p><div class="model-choices"><button :class="{ selected: wizardModel === 'arg-nori' }" @click="wizardModel = 'arg-nori'"><img src="/images/ARGNori.webp" alt="ARG Nori" /><span><b>ARG Nori</b><small>arg-nori</small></span></button><button :class="{ selected: wizardModel === 'nori' }" @click="wizardModel = 'nori'"><img src="/images/Nori.webp" alt="Nori" /><span><b>Nori</b><small>nori</small></span></button></div></section>
          <section v-else-if="step === 3" class="wizard-center"><span class="chip teal">AI 大脑</span><h2>连接一个 AI 服务</h2><p>这一步可以跳过，演示不会发送真实请求。</p><div class="card ai-mini"><label>服务类型<select class="input"><option>OpenAI Chat Completions</option><option>OpenAI Responses</option><option>Anthropic</option><option>Google</option></select></label><label>API Key<input v-model="wizardKey" class="input" type="password" placeholder="sk-..." /></label><label>模型<span class="inline"><input v-model="wizardModelName" class="input" disabled placeholder="先获取模型" /><button class="btn primary small" :disabled="wizardBusy" @click="fetchWizardModels">{{ wizardBusy ? '获取中' : '获取模型' }}</button></span></label></div><button class="btn ghost small" @click="step = 4">跳过 <UiIcon name="arrow-right" :size="11" /></button></section>
          <section v-else class="wizard-center ready"><span class="ready-icon"><UiIcon name="sparkles" :size="32" /></span><span class="chip teal">Ready</span><h2>准备完成</h2><p>已经走完首次运行流程。所有演示状态都只保留在本页。</p></section>
        </main>
        <footer class="wizard-footer"><button class="btn ghost" :disabled="step === 0" @click="step--"><UiIcon name="arrow-left" :size="12" /> 上一步</button><button class="btn primary" @click="step < 4 ? step++ : notify('演示完成')">{{ step === 4 ? '开始使用' : '下一步' }} <UiIcon :name="step === 4 ? 'sparkles' : 'arrow-right'" :size="12" /></button></footer>
      </template>

      <template v-else>
        <div class="main-body">
          <aside class="sidebar" :class="{ collapsed }"><nav><button v-for="item in primaryItems" :key="item.key" :class="{ active: primary === item.key }" :title="collapsed ? item.label : undefined" @click="primary = item.key"><i v-if="primary === item.key" /><UiIcon :name="item.icon" :size="16" /><span v-if="!collapsed">{{ item.label }}</span></button></nav><button class="collapse" @click="collapsed = !collapsed"><UiIcon :name="collapsed ? 'arrow-right' : 'arrow-left'" :size="12" /><span v-if="!collapsed">收起侧栏</span></button></aside>
          <main class="workspace">
            <section v-if="primary === 'home'" class="page"><header><div><h2>你好，欢迎回来</h2><p>查看 Nori 的主要状态与常用入口。</p></div><span class="chip teal">伴侣在线</span></header><div class="hero"><div><span class="chip">当前角色 · ARG Nori</span><h3>桌面陪伴已就绪</h3><p>聊天、语音、模型与长期记忆都可以从左侧进入。</p><button class="btn primary small" @click="primary = 'talk'">开始对话 <UiIcon name="arrow-right" :size="11" /></button></div><img src="/logo.png" alt="Nori" /></div><div class="quick"><button @click="primary = 'model'"><UiIcon name="package" :size="15" /><span><b>模型管理</b><small>切换 Live2D</small></span></button><button @click="primary = 'memory'"><UiIcon name="file" :size="15" /><span><b>长期记忆</b><small>查看记忆</small></span></button><button @click="primary = 'settings'"><UiIcon name="settings" :size="15" /><span><b>设置</b><small>AI 与扩展</small></span></button></div></section>
            <section v-else-if="primary === 'talk'" class="page chat"><header><div><h2>和 Nori 对话</h2><p>消息、工具调用与语音入口都在这里。</p></div><span class="chip success">在线</span></header><div class="messages"><div class="bubble assistant">{{ chatReply }}</div></div><div class="composer"><button class="icon-btn" @click="notify('麦克风演示')"><UiIcon name="mic" :size="14" /></button><input v-model="chatInput" placeholder="给 Nori 发一条消息…" @keydown.enter="sendChat" /><button class="btn primary small" @click="sendChat">发送</button></div></section>
            <section v-else-if="primary === 'model'" class="page"><header><div><h2>模型管理</h2><p>切换模型并调整显示效果。</p></div></header><div class="card"><h3>已安装模型</h3><div class="model-grid"><button :class="{ selected: selectedModel === 'arg-nori' }" @click="selectedModel = 'arg-nori'"><img src="/images/ARGNori.webp" alt="ARG Nori" /><span><b>ARG Nori</b><small>arg-nori</small></span></button><button :class="{ selected: selectedModel === 'nori' }" @click="selectedModel = 'nori'"><img src="/images/Nori.webp" alt="Nori" /><span><b>Nori</b><small>nori</small></span></button></div></div><div class="card"><h3>显示调整</h3><label class="slider">缩放 <b>{{ Math.round(modelScale * 100) }}%</b><input v-model.number="modelScale" type="range" min="0.5" max="2" step="0.05" /></label><div class="pills"><button v-for="name in ['默认', '微笑', '认真', '惊讶']" :key="name" :class="{ on: expression === name }" @click="expression = name">{{ name }}</button></div></div></section>
            <section v-else-if="primary === 'memory'" class="page"><header><div><h2>长期记忆</h2><p>搜索、查看和归档保存的记忆。</p></div></header><input v-model="memoryQuery" class="input" placeholder="搜索记忆…" /><div class="card memory-item"><UiIcon name="file" :size="14" /><span>{{ memoryQuery ? `与「${memoryQuery}」相关的演示记忆` : 'Nori 的界面偏好深海蓝与青色高光' }}</span><button class="btn ghost small" @click="archived = !archived">{{ archived ? '恢复' : '归档' }}</button></div></section>
            <section v-else class="settings-shell"><nav class="settings-nav"><input class="input" placeholder="搜索设置…" /><button v-for="item in settingItems" :key="item.key" :class="{ active: setting === item.key }" @click="setting = item.key"><UiIcon :name="item.icon" :size="14" />{{ item.label }}</button></nav><div class="settings-content"><div class="crumb">设置 <UiIcon name="arrow-right" :size="10" /><b>{{ settingLabel }}</b></div><div class="settings-page">
              <template v-if="setting === 'ai'"><header><div><h2>AI 与模型</h2><p>配置聊天模型与 Embedding 服务。</p></div></header><div class="card form"><h3>对话模型</h3><label>服务类型<select v-model="aiProvider" class="input" @change="changeProvider"><option value="openai">OpenAI Chat Completions</option><option value="openai_responses">OpenAI Responses</option><option value="anthropic">Anthropic</option><option value="google">Google</option></select></label><label>Base URL<input v-model="aiUrl" class="input" /></label><label>API Key<input v-model="aiKey" class="input" type="password" placeholder="填写演示密钥…" /></label><label>模型<span class="inline"><input v-model="aiModel" class="input" placeholder="先获取模型" /><button class="btn primary small" @click="fakeAi(false)">获取模型</button><button class="btn ghost small" @click="fakeAi(true)">测试连接</button></span></label><small class="status">{{ aiStatus }}</small></div></template>
              <template v-else-if="setting === 'voice'"><header><div><h2>语音</h2><p>调整音量与 TTS。</p></div></header><div class="card form"><label class="slider">音量 <b>{{ volume }}%</b><input v-model.number="volume" type="range" min="0" max="100" /></label><div class="pills"><button v-for="name in ['openai','gemini','minimax','indextts','custom','gpt_sovits']" :key="name" :class="{ on: ttsProvider === name }" @click="ttsProvider = name">{{ name === 'gpt_sovits' ? 'GPT-SoVITS' : name === 'indextts' ? 'IndexTTS' : name }}</button></div><label class="slider">语速 <b>{{ ttsSpeed.toFixed(1) }}x</b><input v-model.number="ttsSpeed" type="range" min="0.5" max="2" step="0.1" /></label><label class="toggle"><span><b>自动朗读回复</b><small>生成回复后自动播放</small></span><input v-model="autoplay" type="checkbox" /></label><button class="btn primary small" @click="testVoice">试听当前音色</button><small class="status">{{ voiceStatus }}</small></div></template>
              <template v-else-if="setting === 'skills'"><header><div><h2>技能</h2><p>控制对话中可用的能力。</p></div></header><div class="card toggles"><label><span><b>网页信息</b><small>公开网页信息能力</small></span><input v-model="skillWeb" type="checkbox" /></label><label><span><b>提醒</b><small>创建和管理提醒</small></span><input v-model="skillReminder" type="checkbox" /></label></div></template>
              <template v-else-if="setting === 'mcp'"><header><div><h2>MCP</h2><p>连接外部工具服务。</p></div></header><div class="card toggles"><label><span><b>Demo MCP Server</b><small>3 个演示工具</small></span><input v-model="mcpEnabled" type="checkbox" /></label><button class="btn ghost small" @click="notify('MCP 连接测试成功 · 演示')">测试连接</button></div></template>
              <template v-else-if="setting === 'plugins'"><header><div><h2>插件</h2><p>管理本地 NPS 插件。</p></div></header><div class="card toggles"><label><span><b>Example Plugin</b><small>聊天卡片可用</small></span><input v-model="pluginEnabled" type="checkbox" /></label><button class="btn primary small" @click="notify('已模拟选择 .noripack 文件')">安装本地插件</button></div></template>
              <template v-else-if="setting === 'automation'"><header><div><h2>自动化</h2><p>管理桌面自动化开关。</p></div></header><div class="card toggles"><label><span><b>允许自动化</b><small>演示不会控制真实桌面</small></span><input v-model="automationEnabled" type="checkbox" /></label></div></template>
              <template v-else><header><div><h2>调试与诊断</h2><p>导出经过处理的诊断信息。</p></div></header><div class="card form"><button class="btn primary small" @click="diagnostics = '已生成演示诊断包 · 未读取真实日志'"><UiIcon name="download" :size="12" /> 导出诊断信息</button><small class="status">{{ diagnostics }}</small></div></template>
            </div></div></section>
          </main>
        </div>
        <footer class="footer"><span class="chip" :class="{ success: petVisible }">● 伴侣：{{ petVisible ? '在线' : '隐藏' }} <span class="mono">(ARG Nori)</span></span><div><button class="btn ghost small" @click="reset(); notify('已恢复预览起始位置')"><UiIcon name="refresh" :size="11" /> 重置</button><button class="btn primary" @click="petVisible = !petVisible">{{ petVisible ? '收起 Nori' : '唤出 Nori' }}</button></div></footer>
      </template>
      <div v-if="toast" class="toast">{{ toast }}</div>
    </div>
    <p class="caption"><span class="chip teal">交互演示</span>外观与结构按当前 Nori Desktop 制作；所有操作只保存在本页。</p>
  </div>
</template>

<style scoped>
